const sections = [
  {id:'sellout',label:'Sell Out',glyph:'↗',tabs:['Resumo','Redes','Gerencial']},
  {id:'pex',label:'PEX',glyph:'◫',tabs:[] ,badge:'NOVO'},
  {id:'estoque',label:'Estoque',glyph:'▦',tabs:['Visão Geral','Produtos','Lançamentos','Entradas e Saídas']},
  {id:'atividades',label:'Atividades',glyph:'✓',tabs:['Criação de Combo']},
  {id:'sortimento',label:'Clientes e Sortimento',glyph:'⌘',tabs:['Visão Geral','Sortimento','Lançamentos','Promoções']},
  {id:'relatorios',label:'Documentos',glyph:'▤',tabs:[]},
  {id:'administracao',label:'Administração',glyph:'⚙',tabs:['Bases','Cadastros','Metas','Competências','Auditoria','Dados Canônicos','Sincronização']}
];
let active = 'estoque', activeTab = 0;
const $ = s => document.querySelector(s);
const money = v => `R$ ${v}`;
const metric = (label,value,foot='',tone='') => `<article class="card metric-card"><div class="metric-label">${label}</div><div class="metric-value ${tone}">${value}</div>${foot.includes('%')?`<div class="progress"><span style="width:${parseInt(foot)||0}%"></span></div>`:''}<div class="metric-foot">${foot}</div></article>`;
const pill = (text,tone='good') => `<span class="pill ${tone}">${text}</span>`;
const table = (heads, rows) => `<div class="table-wrap"><table class="data-table"><thead><tr>${heads.map(x=>`<th>${x}</th>`).join('')}</tr></thead><tbody>${rows.map(r=>`<tr>${r.map(x=>`<td>${x}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;
function header(eyebrow,title,description,action='') { return `<div class="page-header"><div><div class="eyebrow">${eyebrow}</div><h2>${title}</h2><p>${description}</p></div>${action}</div>` }
function filters(labels=['Todos','Linha Profissional','Linha Casa','Linha Oral']) {return `<div class="filter-row">${labels.map((x,i)=>`<button class="filter-chip ${i===0?'active':''}" data-filter>${x}</button>`).join('')}<span class="sync-copy">DADOS DEMONSTRATIVOS · ATUALIZADO 21:40</span></div>`}
function chart(values=[90,82,75,69,65,58,46,38]) {return `<div class="bar-chart">${values.map((v,i)=>`<div class="bar-group"><div class="bar ${v<62?'low':''}" style="height:${v}%;--op:${1-i*.065}"></div><span class="bar-label">${['Jan','Fev','Mar','Abr','Mai','Jun','Jul','Ago'][i]}</span></div>`).join('')}</div>`}
function lineChart() {return `<div class="line-chart"><svg viewBox="0 0 560 205" preserveAspectRatio="none"><defs><linearGradient id="fade" x1="0" y1="0" x2="0" y2="1"><stop stop-color="#e11429" stop-opacity=".32"/><stop offset="1" stop-color="#e11429" stop-opacity="0"/></linearGradient></defs><path d="M10 158 L80 143 L150 151 L220 117 L290 125 L360 93 L430 74 L500 41 L550 24 L550 184 L10 184Z" fill="url(#fade)"/><path d="M10 158 L80 143 L150 151 L220 117 L290 125 L360 93 L430 74 L500 41 L550 24" fill="none" stroke="#e11429" stroke-width="2.8" stroke-linecap="round"/><circle cx="550" cy="24" r="5" fill="#e11429"/><circle cx="550" cy="24" r="10" fill="#e11429" opacity=".22"/><text x="510" y="14" fill="#f2f2f0" font-size="12" font-family="IBM Plex Mono">842</text></svg><div class="axis-labels"><span>Jan</span><span>Fev</span><span>Mar</span><span>Abr</span><span>Mai</span><span>Jun</span><span>Jul</span><span>Ago</span><span>Set</span></div></div>`}
function overviewStock(){return `${header('ESTOQUE / VISÃO GERAL','Estoque em operação','Uma leitura rápida de estoque, carteira e cobertura por linha comercial.', '<button class="primary-button" data-toast="Atualização apenas visual">Atualizar bases</button>')}${filters(['Todos os itens','Disponível','Em risco','Com carteira'])}<div class="kpi-grid">${metric('Estoque a custo',money('1.842.560'),'82% do valor a venda')}${metric('Estoque a venda',money('2.917.840'),'91% dos itens precificados')}${metric('Carteira em trânsito',money('428.130'),'18 NFs em aberto','accent')}${metric('Cobertura média','42 dias','<span class="trend">↑ 5 dias vs. agosto</span>')}</div><div class="card-grid">${ringCard('Disponibilidade','86%','1.482 SKUs com saldo','+3 pts no mês',86)}${ringCard('Itens em risco','12%','207 SKUs para atenção','-18 SKUs no mês',12,'risk')}${ringCard('Projeção de estoque','94%','Meta de cobertura em setembro','Estável',94)}</div><div class="layout-two"><article class="card panel"><div class="panel-title"><h3>Estoque por linha comercial</h3><span>VALOR A VENDA</span></div>${chart([91,80,75,67,58,49,42])}<div class="chart-legend"><span><i></i> Dentro da cobertura</span><span><i class="dim"></i> Abaixo da meta</span></div></article><article class="card panel"><div class="panel-title"><h3>Evolução do estoque</h3><span>ÚLTIMOS 9 MESES</span></div>${lineChart()}</article></div>${stockTable()}`}
function ringCard(title,val,copy,trend,valNum,risk=''){let c=risk?'var(--amber)':'var(--accent)'; return `<article class="card ring-card"><div class="ring" style="--val:${valNum}%;${risk?'background:conic-gradient(var(--amber) var(--val),#2a2a2b 0)':''}" data-label="${val}"></div><div class="ring-copy"><strong>${title}</strong><span>${copy}</span><em style="color:${c}">${trend}</em></div></article>`}
function stockTable(){let rows=[['000174','Creme Dental Total 12','Colgate','1.840','286','1.554',money('48.210'),pill('No alvo')],['000331','Sabonete Protex 85g','Protex','860','120','740',money('22.840'),pill('No alvo')],['000562','Palmolive Naturals 350ml','Palmolive','215','88','127',money('18.430'),pill('Atenção','warning')],['000908','Linha Luminous White','Colgate','96','14','82',money('8.920'),pill('Crítico','bad')]];return `<article class="card table-panel"><div class="panel-title"><div><h3>Produtos com maior impacto</h3><span>VISÃO DE ESTOQUE</span></div><button class="panel-link" data-tab="1">Ver todos os produtos →</button></div>${table(['Cód.','Produto','Linha','Físico','Reservado','Disponível','Valor a venda','Risco'],rows)}<div class="table-note">MOSTRANDO 4 DE 1.786 ITENS · DADOS FICTÍCIOS</div></article>`}
function sellout(){let tab=sections.find(s=>s.id==='sellout').tabs[activeTab]; if(tab==='Redes') return networks(); if(tab==='Gerencial') return management(); return `${header('SELL OUT / RESUMO','Resultado comercial','Acompanhamento consolidado da competência ativa.', '<button class="primary-button" data-toast="Arquivo demonstrativo pronto para exportação">Exportar Excel</button>')}${filters(['Todas as linhas','Profissional','Oral Care','Personal Care'])}<div class="kpi-grid">${metric('Meta T&C',money('3.250.000'),'78% atingido')}${metric('Sell Out',money('2.542.680'),'<span class="trend">↑ 12,4% vs. mês anterior</span>','accent')}${metric('Faturado',money('2.178.940'),'86% do Sell Out')}${metric('Positivados','1.238','91% da meta')}</div><div class="layout-two"><article class="card panel"><div class="panel-title"><h3>Fechamento diário</h3><span>SETEMBRO / 2026</span></div>${lineChart()}</article><article class="card panel"><div class="panel-title"><h3>Vendas por linha</h3><span>PARTICIPAÇÃO</span></div>${chart([94,79,65,58,49])}<div class="chart-legend"><span><i></i> Faturado</span><span><i class="dim"></i> A faturar</span></div></article></div><article class="card table-panel"><div class="panel-title"><h3>Resumo por linha comercial</h3><button class="panel-link" data-tab="2">Abrir visão gerencial →</button></div>${table(['Linha','Faturado','A faturar','Total','Meta','Atingimento'],[['Oral Care',money('824.520'),money('86.210'),money('910.730'),money('1.080.000'),'84,3%'],['Personal Care',money('688.420'),money('112.880'),money('801.300'),money('950.000'),'84,3%'],['Profissional',money('422.310'),money('79.100'),money('501.410'),money('720.000'),'69,6%'],['Home Care',money('243.690'),money('85.550'),money('329.240'),money('500.000'),'65,8%']])}</article>`}
function networks(){return `${header('SELL OUT / REDES','Desempenho por redes','Resultados fictícios para avaliação do layout de redes e clientes estratégicos.')}${filters(['Todas as redes','Hiper & Super','Atacarejo','Farmácias'])}<div class="split-panel"><article class="card panel"><div class="panel-title"><h3>Top redes no período</h3><span>SELL OUT</span></div><div class="rank-list">${[['Comper',92,money('412.860')],['Atacadão',81,money('365.170')],['Fort Atacadista',74,money('316.540')],['Pão de Açúcar',63,money('248.320')],['Drogasil',51,money('181.670')]].map((x,i)=>`<div class="rank-row"><b>0${i+1}</b><span>${x[0]}</span><strong>${x[2]}</strong><div class="rank-progress"><i style="width:${x[1]}%"></i></div></div>`).join('')}</div></article><article class="card panel"><div class="panel-title"><h3>Evolução das redes</h3><span>COMPETÊNCIA ATUAL</span></div>${lineChart()}</article></div><article class="card table-panel"><div class="panel-title"><h3>Rede x meta comercial</h3><span>18 REDES ACOMPANHADAS</span></div>${table(['Rede','Clientes','Meta','Realizado','Atingimento','Status'],[['Comper','86',money('420.000'),money('412.860'),'98,3%',pill('No alvo')],['Atacadão','54',money('430.000'),money('365.170'),'84,9%',pill('No alvo')],['Fort Atacadista','41',money('390.000'),money('316.540'),'81,2%',pill('Atenção','warning')],['Pão de Açúcar','33',money('345.000'),money('248.320'),'72,0%',pill('Atenção','warning')]])}</article>`}
