function activities(){return `${header('ATIVIDADES / CRIAÇÃO DE COMBO','Criação de Combo','Superfície visual para montar combinações comerciais; nada é salvo ou exportado.')}${filters(['Produtos elegíveis','Selecionados','Clientes'])}<div class="split-panel"><article class="card panel"><div class="panel-title"><h3>Produtos do combo</h3><span>3 SELECIONADOS</span></div>${[['Creme Dental Total 12','R$ 12,90'],['Escova SlimSoft','R$ 10,50'],['Enxaguante Plax 500ml','R$ 18,90']].map((x,i)=>`<div class="rank-row"><b>0${i+1}</b><span>${x[0]}</span><strong>${x[1]}</strong><div class="rank-progress"><i style="width:${89-i*13}%"></i></div></div>`).join('')}<button class="ghost-button" data-toast="Seleção fictícia de produtos">Adicionar produto</button></article><article class="card panel"><div class="panel-title"><h3>Condições comerciais</h3><span>SIMULAÇÃO</span></div><div class="kpi-grid" style="grid-template-columns:1fr 1fr">${metric('Preço de tabela',money('42,30'),'por combo')}${metric('Desconto','12%','sugerido','accent')}${metric('Preço praticado',money('37,22'),'por combo')}${metric('Clientes','86','elegíveis')}</div><button class="primary-button" data-toast="Criação de combo simulada" style="margin-top:17px">Gerar combo</button></article></div><article class="card table-panel"><div class="panel-title"><h3>Clientes selecionados</h3><span>86 CLIENTES</span></div>${table(['Cliente','Rede','Perfil','Potencial','Elegível'],[['Comper Norte','Comper','Hiper',money('8.420'),pill('Sim')],['Comper Jardim','Comper','Super',money('5.120'),pill('Sim')],['Atacadão MS','Atacadão','Atacarejo',money('7.870'),pill('Sim')],['Drogasil Centro','Drogasil','Farmácia',money('3.940'),pill('Sim')]])}</article>`}
function documents(){return `${header('DOCUMENTOS','Central de documentos','Ações visuais para relatórios e materiais comerciais do Blue Jacket.')}${filters(['Todos os documentos','Comercial','Gestão','Operação'])}<div class="utility-grid">${[['▤','Painel Sell Out','Consolidado de meta, faturamento e positivação.'],['⌘','Relatório de Redes','Desempenho das redes estratégicas.'],['▦','Estoque e cobertura','Disponibilidade, risco e carteira.'],['◫','Arquivo comercial','Base visual de produtos e clientes.'],['✓','Dossiê interno','Resumo gerencial mensal.'],['↗','Combo comercial','Produtos e condições selecionados.']].map(x=>`<article class="card utility-card"><div class="card-icon">${x[0]}</div><div><h3>${x[1]}</h3><p>${x[2]}</p></div><button class="ghost-button" data-toast="Geração simulada de documento">Gerar documento</button></article>`).join('')}</div>`}
function admin(){let tab=sections.find(s=>s.id==='administracao').tabs[activeTab]; if(tab==='Metas')return targets();if(tab==='Competências')return competences();if(tab==='Auditoria')return audit();if(tab==='Dados Canônicos')return canonical();if(tab==='Sincronização')return sync();return `${header('ADMINISTRAÇÃO / '+tab.toUpperCase(),tab,'Painel visual de configurações e fontes de dados do Blue Jacket.')}${filters(tab==='Cadastros'?['Produtos','Clientes','RCAs','Linhas']:['Todas as fontes','Rotina','Competência','Histórico'])}<div class="kpi-grid">${metric('Fontes registradas','19','3 atualizadas hoje')}${metric('Fontes carregadas','18','94,7% de cobertura')}${metric('Pendências','3','Requerem revisão','accent')}${metric('Última atualização','21:40','22 de setembro')}</div><article class="card table-panel"><div class="panel-title"><h3>${tab==='Cadastros'?'Cadastros operacionais':'Fontes registradas'}</h3><button class="primary-button" data-toast="Fluxo apenas demonstrativo">${tab==='Cadastros'?'Novo cadastro':'Atualizar lote'}</button></div>${table(tab==='Cadastros'?['Tipo','Descrição','Registros','Atualizado em','Status']:['Fonte','Rotina','Competência','Atualizado em','Status'],tab==='Cadastros'?[['Produtos','Cadastro oficial de itens','1.786','22/09/2026',pill('Ativo')],['Clientes','Base de clientes elegíveis','482','22/09/2026',pill('Ativo')],['RCAs','Estrutura comercial','36','20/09/2026',pill('Atenção','warning')],['Linhas','Classificação comercial','5','22/09/2026',pill('Ativo')]]:[['8013 · Cadastro de itens','Operação','Set/2026','22/09 21:40',pill('Carregada')],['8022 · Movimento de vendas','Competência','Set/2026','22/09 21:40',pill('Carregada')],['Carteira Colgate','Operação','Set/2026','22/09 20:55',pill('Carregada')],['Tabela de preços','Apoio','Set/2026','22/09 19:30',pill('Pendente','warning')]])}</article>`}
function targets(){return `${header('ADMINISTRAÇÃO / METAS','Metas','Parâmetros comerciais, distribuição e calendário do período.')}${filters(['Visão geral','Linhas comerciais','Redes','Calendário'])}<div class="kpi-grid">${metric('Meta indústria',money('3.250.000'),'Setembro / 2026')}${metric('Meta positivação','1.360','91% realizado')}${metric('Meta Top redes',money('1.485.000'),'78% realizado')}${metric('Dias úteis','22','18 transcorridos')}</div><article class="card table-panel"><div class="panel-title"><h3>Distribuição comercial</h3><button class="primary-button" data-toast="Edição de metas é somente visual">Editar metas</button></div>${table(['Linha','Meta sell out','Meta positivação','Realizado','Atingimento'],[['Oral Care',money('1.080.000'),'422',money('910.730'),'84,3%'],['Personal Care',money('950.000'),'384',money('801.300'),'84,3%'],['Profissional',money('720.000'),'252',money('501.410'),'69,6%'],['Home Care',money('500.000'),'174',money('329.240'),'65,8%']])}</article>`}
function competences(){return `${header('ADMINISTRAÇÃO / COMPETÊNCIAS','Competências','Competência comercial ativa e registros disponíveis.')}${filters(['Setembro 2026','Histórico','Encerradas'])}<article class="card table-panel"><div class="panel-title"><h3>Calendário de competências</h3><button class="primary-button" data-toast="Troca de competência simulada">Definir competência</button></div>${table(['Competência','Início','Fim','Status','Fontes vinculadas'],[['Setembro / 2026','01/09/2026','30/09/2026',pill('Ativa'),'18 de 19'],['Agosto / 2026','01/08/2026','31/08/2026',pill('Encerrada'),'19 de 19'],['Julho / 2026','01/07/2026','31/07/2026',pill('Encerrada'),'19 de 19']])}</article>`}
function audit(){return `${header('ADMINISTRAÇÃO / AUDITORIA','Auditoria','Registro fictício de verificações e pendências do ambiente.')}${filters(['Todos os eventos','Avisos','Erros','Atualizações'])}<article class="card table-panel"><div class="panel-title"><h3>Eventos recentes</h3><span>ÚLTIMAS 24 HORAS</span></div>${table(['Horário','Evento','Origem','Detalhe','Situação'],[['21:40','Atualização de bases','Rotina mensal','18 fontes materializadas',pill('Concluído')],['21:12','Validação de preços','PCTABPR','3 itens sem PVENDA1',pill('Atenção','warning')],['20:55','Conciliação de carteira','Estoque','1 NF em revisão',pill('Pendente','bad')],['19:30','Backup de competência','Administração','Fotografia salva',pill('Concluído')]])}</article>`}
function canonical(){return `${header('ADMINISTRAÇÃO / DADOS CANÔNICOS','Dados Canônicos','Resumo visual do bundle ativo e suas listas materializadas.')}${filters(['Bundle ativo','Listas','Histórico'])}<div class="kpi-grid">${metric('Build ativo','v2026.09.22','assinatura válida')}${metric('Listas canônicas','5','todas disponíveis')}${metric('Registros','84.216','base materializada')}${metric('Integridade','100%','sem falhas','accent')}</div><article class="card table-panel"><div class="panel-title"><h3>Listas materializadas</h3><span>BUNDLE ATIVO</span></div>${table(['Lista','Descrição','Registros','Competência','Estado'],[['M1','Item e estoque','1.786','Set/2026',pill('Disponível')],['M2','Cliente e RCA','482','Set/2026',pill('Disponível')],['M3','Movimento de vendas','79.441','Set/2026',pill('Disponível')],['M4','Histórico de transição','2.507','Set/2026',pill('Disponível')]])}</article>`}
function sync(){return `${header('ADMINISTRAÇÃO / SINCRONIZAÇÃO','Sincronização','Acompanhamento visual de snapshots e dispositivos vinculados.')}${filters(['Status atual','Histórico','Dispositivos'])}<div class="kpi-grid">${metric('Última sincronização','21:40','22 de setembro')}${metric('Dispositivos','3','todos atualizados')}${metric('Snapshots','28','últimos 90 dias')}${metric('Fila pendente','0','nenhuma operação','accent')}</div><article class="card table-panel"><div class="panel-title"><h3>Histórico de sincronização</h3><button class="primary-button" data-toast="Sincronização simulada com sucesso">Sincronizar agora</button></div>${table(['Data e hora','Dispositivo','Ação','Snapshot','Status'],[['22/09 21:40','Desktop MCD','Atualização completa','snap_4829',pill('Concluída')],['22/09 18:10','Notebook Comercial','Leitura de snapshot','snap_4829',pill('Concluída')],['21/09 20:55','Desktop MCD','Backup de competência','snap_4828',pill('Concluída')]])}</article>`}
function pex(){return `${header('PEX','PEX — Painel de Execução','Estrutura visual reservada para o módulo PEX do Blue Jacket.')}${filters(['Visão geral','Indicadores','Auditorias'])}<article class="card placeholder"><div class="placeholder-icon">◫</div><h2>Módulo PEX em construção</h2><p>O espaço e os controles foram preservados no protótipo visual. Os indicadores aparecerão aqui quando o módulo estiver disponível.</p><button class="ghost-button" data-toast="Módulo ainda sem lógica operacional" style="margin-top:18px">Conhecer estrutura</button></article>`}
function render(){let section=sections.find(s=>s.id===active);$('#primary-nav').innerHTML=sections.map(s=>`<button class="nav-item ${s.id===active?'active':''}" data-section="${s.id}"><span class="nav-glyph">${s.glyph}</span><span>${s.label}</span>${s.badge?`<span class="side-badge">${s.badge}</span>`:''}</button>`).join(''); $('#breadcrumb').textContent=`BLUE JACKET / ${section.label.toUpperCase()}`; $('#page-title').textContent=section.label; $('#subtabs').innerHTML=section.tabs.length?section.tabs.map((t,i)=>`<button class="subtab ${activeTab===i?'active':''}" data-tab="${i}">${t}</button>`).join(''):'';let page=active==='estoque'?(activeTab===0?overviewStock():products()):active==='sellout'?sellout():active==='sortimento'?assortment():active==='atividades'?activities():active==='relatorios'?documents():active==='administracao'?admin():pex(); $('#page-content').innerHTML=page; bind();}
function bind(){document.querySelectorAll('[data-section]').forEach(b=>b.onclick=()=>{active=b.dataset.section;activeTab=0;render();$('#sidebar').classList.remove('open')});document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>{activeTab=Number(b.dataset.tab);render()});document.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>{document.querySelectorAll('[data-filter]').forEach(x=>x.classList.remove('active'));b.classList.add('active');toast(`Filtro visual: ${b.textContent}`)});document.querySelectorAll('[data-toast]').forEach(b=>b.onclick=()=>toast(b.dataset.toast));}
let timer;function toast(message){let el=$('#toast');el.textContent=message;el.classList.add('show');clearTimeout(timer);timer=setTimeout(()=>el.classList.remove('show'),2700)}
$('#menu-button').onclick=()=>$('#sidebar').classList.toggle('open');$('#global-search').addEventListener('input',e=>{if(e.target.value.length>2)toast(`Busca visual por “${e.target.value}”`)});render();
